// ── 로그 헬퍼 ───────────────────────────────────────────────
// L(...) 로 남긴 기록은 두 곳에서 보인다.
//   1) 편집 화면에서 이 노드를 실행하면  → 출력 패널의 'Logs' 탭 (console.log)
//   2) 모든 실행 (프로덕션 포함)         → 출력 데이터의 _log 필드
const _log = [];
const L = (...a) => {
  const s = a.map(v => (typeof v === 'object' ? JSON.stringify(v) : String(v))).join(' ');
  _log.push(s);
  console.log('[경보 파싱] ' + s);
};
// ───────────────────────────────────────────────────────────
// [수집] SIEM이 보낸 원본 경보를 플레이북이 쓰기 좋은 공통 필드로 정규화한다.
// 실제 환경에서는 제품마다 필드명이 제각각이라 이 단계가 반드시 필요하다.
const a = $json.body ?? $json;
L('원본 경보 수신:', a);

const out = {
  alert_id: a.alert_id ?? ('ALERT-' + Date.now()),
  rule:     a.rule     ?? 'unknown-rule',
  severity: String(a.severity ?? 'medium').toLowerCase(),
  src_ip:   a.src_ip   ?? a.source_ip ?? '0.0.0.0',
  host:     a.host     ?? '-',
  user:     a.user     ?? '-',
  received_at: new Date().toISOString(),
};

L(`정규화 완료 → rule=${out.rule} severity=${out.severity} src_ip=${out.src_ip} host=${out.host} user=${out.user}`);
if (out.src_ip === '0.0.0.0') L('!! 경고: src_ip 를 찾지 못했다. 필드명이 다른 SIEM 인지 확인할 것');

return [{ json: { ...out, _log } }];

// ── 로그 헬퍼 ───────────────────────────────────────────────
// L(...) 로 남긴 기록은 두 곳에서 보인다.
//   1) 편집 화면에서 이 노드를 실행하면  → 출력 패널의 'Logs' 탭 (console.log)
//   2) 모든 실행 (프로덕션 포함)         → 출력 데이터의 _log 필드
const _log = [];
const L = (...a) => {
  const s = a.map(v => (typeof v === 'object' ? JSON.stringify(v) : String(v))).join(' ');
  _log.push(s);
  console.log('[위험도 산정] ' + s);
};
// ───────────────────────────────────────────────────────────
// [판정] 경보 심각도와 외부 평판을 합쳐 위험도를 산정한다.
// HTTP 노드를 지나면 $json 이 평판 응답으로 바뀌므로, 경보 원본은 이름으로 참조한다.
const alert = $('경보 파싱').first().json;
const rep   = $json;

const SEV  = { low: 10, medium: 30, high: 55, critical: 70 };
const base = SEV[alert.severity] ?? 30;

L(`경보  : ${alert.rule} · ${alert.host}/${alert.user} · severity=${alert.severity} → 가중치 ${base}`);
L(`평판  : score=${rep.score} country=${rep.country} asn=${rep.asn} cats=[${(rep.categories || []).join(',')}] internal=${rep.internal === true}`);

const risk = Math.min(100, Math.round(rep.score * 0.7 + base * 0.5));
L(`계산  : round(${rep.score} × 0.7 + ${base} × 0.5) = ${risk}`);

const decision = risk >= 80 ? 'block' : 'close';
L(`판정  : ${decision}  (임계값 80, 위험도 ${risk})`);

return [{
  json: {
    ...alert,
    reputation: rep.score,
    country: rep.country,
    asn: rep.asn,
    categories: (rep.categories || []).join(',') || '-',
    internal: rep.internal === true,
    risk_score: risk,
    decision,
    rationale: `severity=${alert.severity}(${base}) + reputation=${rep.score} -> risk=${risk}`,
    _log: [ ...(alert._log || []), ..._log ],
  }
}];

// ── 로그 헬퍼 ───────────────────────────────────────────────
// L(...) 로 남긴 기록은 두 곳에서 보인다.
//   1) 편집 화면에서 이 노드를 실행하면  → 출력 패널의 'Logs' 탭 (console.log)
//   2) 모든 실행 (프로덕션 포함)         → 출력 데이터의 _log 필드
const _log = [];
const L = (...a) => {
  const s = a.map(v => (typeof v === 'object' ? JSON.stringify(v) : String(v))).join(' ');
  _log.push(s);
  console.log('[예외 목록 확인] ' + s);
};
// ───────────────────────────────────────────────────────────
// [예외 처리] 자동 차단하면 안 되는 대상을 걸러낸다.
// !! 이 노드는 처음에 '비활성'으로 배포되어 있다. 오탐 사고를 먼저 재현한 뒤 활성화할 것.
const ALLOWLIST = ['203.0.113.77'];   // 사내 취약점 스캐너 (외부 TI 에는 scanner 로 등재됨)
const j = $json;
const isPrivate = /^(10\.|192\.168\.|172\.(1[6-9]|2\d|3[01])\.)/.test(j.src_ip);

L(`검사 대상: ${j.src_ip} (현재 판정 ${j.decision}, 위험도 ${j.risk_score})`);
L(`예외 목록: [${ALLOWLIST.join(', ')}] · 내부 대역 여부=${isPrivate}`);

if (ALLOWLIST.includes(j.src_ip) || isPrivate) {
  L('→ 예외 대상이다. 자동 차단을 보류(hold)하고 사람 검토로 넘긴다');
  return [{ json: { ...j, decision: 'hold',
    rationale: j.rationale + ' | 예외 목록 대상 — 자동 차단 보류, 사람 검토 필요',
    _log: [ ...(j._log || []), ..._log ] } }];
}

L(`→ 예외 아님. 판정 유지: ${j.decision}`);
return [{ json: { ...j, _log: [ ...(j._log || []), ..._log ] } }];

// ── 로그 헬퍼 ───────────────────────────────────────────────
// L(...) 로 남긴 기록은 두 곳에서 보인다.
//   1) 편집 화면에서 이 노드를 실행하면  → 출력 패널의 'Logs' 탭 (console.log)
//   2) 모든 실행 (프로덕션 포함)         → 출력 데이터의 _log 필드
const _log = [];
const L = (...a) => {
  const s = a.map(v => (typeof v === 'object' ? JSON.stringify(v) : String(v))).join(' ');
  _log.push(s);
  console.log('[차단 실행] ' + s);
};
// ───────────────────────────────────────────────────────────
const res = $json;
const src = $('자동 차단 대상인가').first().json;
L(`대상 ${src.src_ip} · 사유 ${src.rule} · 위험도 ${src.risk_score}`);
L('방화벽 응답:', res);
L(res.idempotent ? '→ 이미 차단되어 있던 IP 다 (멱등 — 상태 변화 없음)' : '→ 새로 차단했다');
L('!! 되돌리기 어려운 구간을 지났다. 오탐이면 Lab 4 롤백이 필요하다');
return [{ json: { ...res, _log: [ ...(res._log || []), ..._log ] } }];
